import{_ as i,o,c as r,a3 as t}from"./chunks/framework.DACwFHq9.js";const h=JSON.parse('{"title":"Audio Recording & Speech-to-Text","description":"Record voice notes, conference meetings with dual-stream audio loopback, and generate AI transcripts with local Whisper.","frontmatter":{"title":"Audio Recording & Speech-to-Text","description":"Record voice notes, conference meetings with dual-stream audio loopback, and generate AI transcripts with local Whisper.","keywords":"audio recording, voice notes, meeting recorder, speech to text, whisper, transcription, transcript drawer","category":"Workspace"},"headers":[],"relativePath":"workspace/audio-recording.md","filePath":"workspace/audio-recording.md","lastUpdated":1790577173000}'),a={name:"workspace/audio-recording.md"};function n(s,e,d,l,c,g){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="audio-recording-speech-to-text" tabindex="-1">Audio Recording &amp; Speech-to-Text <a class="header-anchor" href="#audio-recording-speech-to-text" aria-label="Permalink to &quot;Audio Recording &amp; Speech-to-Text&quot;">​</a></h1><p>Notely includes a dual-stream audio recording engine and speech-to-text pipeline for voice notes and conference call transcriptions.</p><hr><h2 id="_1-recording-modes" tabindex="-1">1. Recording Modes <a class="header-anchor" href="#_1-recording-modes" aria-label="Permalink to &quot;1. Recording Modes&quot;">​</a></h2><p>Trigger audio recording via <code>Alt + V</code>, the <strong>🎙️ Record Audio</strong> toolbar button in the Markdown editor, or the <strong>Quick Capture Bar</strong> on the landing dashboard.</p><ol><li><strong>Meeting Mode (Mic + System Loopback)</strong>: <ul><li>Captures microphone input and Windows system audio (Zoom, Google Meet, Microsoft Teams, YouTube) concurrently.</li><li>Merges both streams into a synchronized stereo track via Web Audio API.</li></ul></li><li><strong>Microphone Only</strong>: <ul><li>Voice memo and dictation capture from your primary recording device.</li></ul></li><li><strong>System Audio Only</strong>: <ul><li>Records desktop/speaker audio output without microphone commentary.</li></ul></li></ol><hr><h2 id="_2-speech-to-text-stt-engines" tabindex="-1">2. Speech-to-Text (STT) Engines <a class="header-anchor" href="#_2-speech-to-text-stt-engines" aria-label="Permalink to &quot;2. Speech-to-Text (STT) Engines&quot;">​</a></h2><p>Configure STT preferences in <strong>AI -&gt; AI Settings -&gt; Speech-to-Text</strong>:</p><ul><li><strong>Local ONNX Whisper (Offline)</strong>: <ul><li>Runs on-device via WebAssembly/ONNX Runtime.</li><li>Models: <code>whisper-tiny.en</code> (~40MB), <code>whisper-base.en</code> (~140MB), <code>whisper-small</code> (~460MB).</li><li>Private, zero external network traffic.</li></ul></li><li><strong>Cloud Whisper</strong>: <ul><li>High-throughput cloud transcription via <strong>Groq</strong> (<code>whisper-large-v3</code>) or <strong>OpenAI</strong> (<code>whisper-1</code>).</li><li>Sub-second turnaround using your configured API keys.</li></ul></li></ul><hr><h2 id="_3-storage-markdown-integration" tabindex="-1">3. Storage &amp; Markdown Integration <a class="header-anchor" href="#_3-storage-markdown-integration" aria-label="Permalink to &quot;3. Storage &amp; Markdown Integration&quot;">​</a></h2><ul><li><strong>Audio Files</strong>: Stored in <code>{workspace}/media/audio/*.webm</code>.</li><li><strong>Transcripts</strong>: Stored alongside audio files in <code>{workspace}/media/audio/*.json</code>.</li><li><strong>Note Insertion</strong>: Inserting a recording places both the audio player and transcript block at your cursor:<div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Audio Recording</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">media/audio/recording-2026-09-26.webm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul><hr><h2 id="_4-diagrams-media-gallery-integration" tabindex="-1">4. Diagrams &amp; Media Gallery Integration <a class="header-anchor" href="#_4-diagrams-media-gallery-integration" aria-label="Permalink to &quot;4. Diagrams &amp; Media Gallery Integration&quot;">​</a></h2><ul><li>Filter by the <strong>Transcripts</strong> and <strong>Audio</strong> categories in <code>Workspace -&gt; Diagrams &amp; Media Gallery</code> (<code>Ctrl/Cmd + Alt + M</code>).</li><li><strong>On-Demand AI Transcript Generation (<code>✨</code>)</strong>: Run speech-to-text on any existing recording without re-recording.</li></ul>',16)])])}const u=i(a,[["render",n]]);export{h as __pageData,u as default};
